  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Faltam as precedências necessárias para determinar se e quanto o término muda."
    ],
    "motivo": "A duração alterada é conhecida, mas seu efeito sobre o término final não pode ser calculado sem a rede de precedências.",
    "unidade": "dia_corrido"
  },
