        "localizador": "L02"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base declara R$ 1.650,00, consistente com as obrigações fixas e o apoio contratado.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "O aviso não tem custo direto. Com as demais condições inalteradas, a redução de duração não eleva o término; se houver antecipação, a cláusula sem crédito preserva os R$ 650,00 do apoio. As parcelas fixas também não variam com o prazo.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "exato",
    "valor": 0,
    "direcao": "zero",
    "evidencias": [
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "Não há custo direto; as parcelas fixas permanecem iguais e a política sem crédito mantém o valor do apoio se o término for antecipado.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O aviso reduz a duração de emitir dossiê, mas a view não apresenta as precedências que determinariam o efeito no término. O custo permanece no valor base: não há custo direto, as parcelas são fixas e eventual antecipação não reduz o apoio contratado."
}

